import hmac
import hashlib
import os
import sqlite3
from flask import Flask, request, jsonify, g
from functools import wraps

app = Flask(__name__)
app.config['SECRET_KEY'] = os.urandom(32)
app.config['DATABASE'] = ':memory:'

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(app.config['DATABASE'])
        g.db.row_factory = sqlite3.Row
        init_db(g.db)
    return g.db

def init_db(db):
    db.execute('CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY, username TEXT UNIQUE, role TEXT, api_key TEXT)')
    db.execute('CREATE TABLE IF NOT EXISTS documents (id INTEGER PRIMARY KEY, owner_id INTEGER, title TEXT, content TEXT, classification TEXT)')
    db.execute("INSERT OR IGNORE INTO users (id, username, role, api_key) VALUES (1, 'admin', 'admin', 'ak_admin_secret')")
    db.execute("INSERT OR IGNORE INTO users (id, username, role, api_key) VALUES (2, 'analyst', 'analyst', 'ak_analyst_key')")
    db.execute("INSERT OR IGNORE INTO documents (id, owner_id, title, content, classification) VALUES (1, 1, 'Secret Plans', 'Top secret content here', 'TOP_SECRET')")
    db.execute("INSERT OR IGNORE INTO documents (id, owner_id, title, content, classification) VALUES (2, 2, 'Analysis Report', 'Regular analysis', 'INTERNAL')")
    db.commit()

def verify_api_key(api_key):
    db = get_db()
    user = db.execute('SELECT * FROM users WHERE api_key = ?', (api_key,)).fetchone()
    return user

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        api_key = request.headers.get('X-API-Key', '')
        user = verify_api_key(api_key)
        if not user:
            return jsonify({'error': 'Unauthorized'}), 401
        g.current_user = user
        return f(*args, **kwargs)
    return decorated

def check_access(user, document):
    """Multi-level access control check.
    Admins can access everything.
    Analysts can access INTERNAL and below.
    Regular users can only access PUBLIC."""
    classification_levels = {
        'PUBLIC': 0,
        'INTERNAL': 1,
        'CONFIDENTIAL': 2,
        'TOP_SECRET': 3
    }
    role_max_level = {
        'admin': 3,
        'analyst': 1,
        'user': 0
    }
    doc_level = classification_levels.get(document['classification'], 3)
    user_level = role_max_level.get(user['role'], 0)
    return user_level >= doc_level

def build_query_filter(params):
    """Build SQL filter from query parameters with parameterized queries."""
    conditions = []
    values = []

    if 'title' in params:
        conditions.append('title LIKE ?')
        values.append(f"%{params['title']}%")

    if 'classification' in params:
        conditions.append('classification = ?')
        values.append(params['classification'])

    if 'owner_id' in params:
        conditions.append('owner_id = ?')
        values.append(params['owner_id'])

    return conditions, values

@app.route('/api/documents', methods=['GET'])
@require_auth
def list_documents():
    db = get_db()
    user = g.current_user

    conditions, values = build_query_filter(request.args)

    base_query = 'SELECT * FROM documents'
    if conditions:
        base_query += ' WHERE ' + ' AND '.join(conditions)

    documents = db.execute(base_query, values).fetchall()

    # Apply access control filtering on results
    accessible_docs = []
    for doc in documents:
        if check_access(user, doc):
            accessible_docs.append({
                'id': doc['id'],
                'title': doc['title'],
                'classification': doc['classification']
            })

    return jsonify({'documents': accessible_docs})

@app.route('/api/documents/<int:doc_id>', methods=['GET'])
@require_auth
def get_document(doc_id):
    db = get_db()
    user = g.current_user

    doc = db.execute('SELECT * FROM documents WHERE id = ?', (doc_id,)).fetchone()
    if not doc:
        return jsonify({'error': 'Not found'}), 404

    if not check_access(user, doc):
        return jsonify({'error': 'Access denied'}), 403

    return jsonify({
        'id': doc['id'],
        'title': doc['title'],
        'content': doc['content'],
        'classification': doc['classification']
    })

@app.route('/api/documents/search', methods=['POST'])
@require_auth
def search_documents():
    db = get_db()
    user = g.current_user

    data = request.get_json()
    if not data or 'query' not in data:
        return jsonify({'error': 'Missing query'}), 400

    search_query = data['query']
    sort_field = data.get('sort', 'id')

    # Whitelist allowed sort fields
    allowed_sorts = ['id', 'title', 'classification']
    if sort_field not in allowed_sorts:
        sort_field = 'id'

    # Build search query - parameterized
    sql = f"SELECT * FROM documents WHERE title LIKE ? OR content LIKE ? ORDER BY {sort_field}"
    pattern = f"%{search_query}%"
    documents = db.execute(sql, (pattern, pattern)).fetchall()

    # Filter by access level
    results = []
    for doc in documents:
        if check_access(user, doc):
            results.append({
                'id': doc['id'],
                'title': doc['title'],
                'classification': doc['classification']
            })

    return jsonify({'results': results})

@app.route('/api/documents/export', methods=['POST'])
@require_auth
def export_documents():
    db = get_db()
    user = g.current_user

    data = request.get_json()
    if not data or 'doc_ids' not in data:
        return jsonify({'error': 'Missing doc_ids'}), 400

    doc_ids = data['doc_ids']
    if not isinstance(doc_ids, list) or len(doc_ids) > 100:
        return jsonify({'error': 'Invalid doc_ids'}), 400

    # Validate all IDs are integers
    try:
        validated_ids = [int(did) for did in doc_ids]
    except (ValueError, TypeError):
        return jsonify({'error': 'Invalid ID format'}), 400

    placeholders = ','.join(['?'] * len(validated_ids))
    sql = f"SELECT * FROM documents WHERE id IN ({placeholders})"
    documents = db.execute(sql, validated_ids).fetchall()

    # Access control check
    exported = []
    for doc in documents:
        if check_access(user, doc):
            exported.append({
                'id': doc['id'],
                'title': doc['title'],
                'content': doc['content'],
                'classification': doc['classification']
            })

    return jsonify({'exported': exported})

@app.route('/api/admin/grant-access', methods=['POST'])
@require_auth
def grant_access():
    user = g.current_user

    # Check admin role
    if user['role'] != 'admin':
        return jsonify({'error': 'Admin only'}), 403

    data = request.get_json()
    target_user = data.get('username')
    new_role = data.get('role')

    allowed_roles = ['user', 'analyst']
    if new_role not in allowed_roles:
        return jsonify({'error': 'Invalid role'}), 400

    db = get_db()
    db.execute('UPDATE users SET role = ? WHERE username = ?', (new_role, target_user))
    db.commit()

    return jsonify({'status': 'updated'})

@app.route('/api/profile', methods=['GET'])
@require_auth
def get_profile():
    user = g.current_user
    return jsonify({
        'id': user['id'],
        'username': user['username'],
        'role': user['role']
    })

@app.route('/api/profile/update', methods=['POST'])
@require_auth
def update_profile():
    user = g.current_user
    data = request.get_json()

    if not data:
        return jsonify({'error': 'No data'}), 400

    allowed_fields = ['username']
    updates = {}
    for field in allowed_fields:
        if field in data:
            updates[field] = data[field]

    if not updates:
        return jsonify({'error': 'No valid fields'}), 400

    db = get_db()
    for field, value in updates.items():
        db.execute(f"UPDATE users SET {field} = ? WHERE id = ?", (value, user['id']))
    db.commit()

    return jsonify({'status': 'updated'})

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

if __name__ == '__main__':
    app.run(debug=False)
